import type {Timeline} from '../timeline/timeline';
import {boardEvents, boardState} from '../board/board';
import {flowState} from '../scenes/flowState';
import type {SfxName} from '../spec/vocab';

// Sound effects derived from the same events that drive the animation, so every pop,
// whoosh and buzz lands exactly on its visual. Files live in public/sfx/
// (generated by scripts/make-sfx.sh).

export type SoundKind = SfxName;
export type SoundEvent = {t: number; kind: SoundKind; volume: number};

const VOLUME: Record<SoundKind, number> = {
  pop: 0.32, whoosh: 0.2, error: 0.45, success: 0.38, impact: 0.5,
  cash: 0.42, clock: 0.4, notify: 0.4, alarm: 0.22, riser: 0.3, type: 0.3,
};
// Minimum gap between two sounds of the same kind (seconds).
const MIN_GAP: Record<SoundKind, number> = {
  pop: 0.12, whoosh: 0.3, error: 0.8, success: 0.8, impact: 0.5,
  cash: 0.8, clock: 1.2, notify: 0.8, alarm: 1.2, riser: 1.5, type: 1,
};
export const SOUND_SECONDS: Record<SoundKind, number> = {
  pop: 0.2, whoosh: 0.5, error: 0.7, success: 0.9, impact: 0.8,
  cash: 1, clock: 1.1, notify: 0.7, alarm: 1, riser: 1.3, type: 0.9,
};
// The riser builds up to the cue instead of starting on it.
const LEAD: Partial<Record<SoundKind, number>> = {riser: 1.15};

export function soundEvents(tl: Timeline): SoundEvent[] {
  const raw: {t: number; kind: SoundKind; gain?: number}[] = [];
  const add = (t: number, kind: SoundKind, gain = 1) => raw.push({t: Math.max(0, t), kind, gain});
  // Author cues ("sfx" on a step, item or scene).
  const cue = (t: number, kind?: SfxName) => {
    if (kind) add(t - (LEAD[kind] ?? 0), kind);
  };

  for (const s of tl.scenes) {
    if (s.index === 0) add(0.05, 'impact', 0.7);
    else if (s.type !== 'callout') add(s.start, 'whoosh', 0.7);

    if (s.type === 'title' || s.type === 'callout') cue(s.start + 0.15, s.sfx);
    if (s.type === 'title')
      (s.beats ?? []).forEach((b, i) => {
        add(s.start + (s.cues[i] ?? 0), 'pop');
        cue(s.start + (s.cues[i] ?? 0), b.sfx);
      });
    if (s.type === 'flow' || s.type === 'board' || s.type === 'code' || s.type === 'chart' || s.type === 'figure' || s.type === 'sequence') s.steps.forEach((st, i) => cue(s.start + (s.cues[i] ?? 0), st.sfx));
    if (s.type === 'list') s.items.forEach((it, i) => cue(s.start + (s.cues[i] ?? 0), it.sfx));
    if (s.type === 'summary') s.points.forEach((it, i) => cue(s.start + (s.cues[i] ?? 0), it.sfx));
    if (s.type === 'compare') [...s.left.items, ...s.right.items].forEach((it, i) => cue(s.start + (s.cues[i] ?? 0), it.sfx));

    switch (s.type) {
      case 'code':
        add(s.start + 0.3, 'type', 0.7); // the editor types itself
        break;
      case 'callout':
        add(s.start + 0.15, 'impact');
        if (s.tone === 'good') add(s.start + 0.3, 'success');
        break;
      case 'flow': {
        const st = flowState(s, s.cues, s.duration);
        for (const v of Object.values(st.nodes)) if (v.on && v.since > 0.2) add(s.start + v.since, 'pop');
        for (const p of st.packets) add(s.start + p.start, 'whoosh');
        s.steps.forEach((step, i) => {
          if (step.sfx) return; // the author's sound speaks for this moment
          const vals = Object.values(step.status ?? {});
          if (vals.includes('error')) add(s.start + s.cues[i], 'error');
          else if (vals.includes('ok')) add(s.start + s.cues[i], 'success', 0.8);
        });
        break;
      }
      case 'sequence':
        s.steps.forEach((step, i) => {
          if (step.sfx) return; // the author's sound speaks for this moment
          const at = s.start + (s.cues[i] ?? 0);
          const vals = Object.values(step.status ?? {});
          if (step.kind === 'lost' || vals.includes('error')) add(at + 0.3, 'error');
          else if (vals.includes('ok')) add(at + 0.3, 'success', 0.8);
          else if (step.from) add(at, 'whoosh', 0.55);
        });
        break;
      case 'chart':
        s.steps.forEach((step, i) => {
          if (step.sfx) return;
          const at = s.start + (s.cues[i] ?? 0);
          if (step.draw?.length) add(at, 'whoosh', 0.6);
          if (step.mark) add(at + 0.05, 'pop');
        });
        break;
      case 'figure':
        s.steps.forEach((step, i) => {
          if (step.sfx) return;
          const at = s.start + (s.cues[i] ?? 0);
          if (step.signal) add(at, 'whoosh', 0.7);
          if (step.label) add(at + 0.05, 'pop');
          else if (step.glow?.length) add(at, 'pop', 0.6);
        });
        break;
      case 'list':
      case 'compare':
      case 'summary': {
        for (const c of s.cues) add(s.start + c, 'pop');
        if (s.type === 'summary') {
          const last = s.cues[s.cues.length - 1] ?? 0;
          add(s.start + Math.min(Math.max(last + 0.8, s.duration * 0.55), s.duration - 1.2), 'success');
        }
        break;
      }
      default:
        break;
    }
  }

  if (tl.board) {
    const events = boardEvents(tl);
    const end = boardState(tl, tl.duration + 1, events);
    for (const p of end.packets) add(p.start, 'whoosh');
    const seen = new Set<string>();
    for (const ev of events) {
      if (ev.kind !== 'step') continue;
      const after = boardState(tl, ev.t + 0.6, events);
      for (const [id, v] of Object.entries(after.nodes)) {
        if (v.on && v.since >= ev.t - 0.001 && !seen.has(`${id}@${v.since}`)) {
          seen.add(`${id}@${v.since}`);
          add(v.since, 'pop');
        }
      }
      if (ev.step.sfx && ev.step.sfx !== 'riser') continue; // the author's sound speaks for this moment
      const vals = Object.values(ev.step.status ?? {});
      if (vals.includes('error')) add(ev.t, 'error');
      else if (vals.includes('ok')) add(ev.t, 'success', 0.8);
    }
  }

  raw.sort((a, b) => a.t - b.t);
  const last: Partial<Record<SoundKind, number>> = {};
  const out: SoundEvent[] = [];
  for (const e of raw) {
    if (e.t > tl.duration - 0.05) continue;
    const prev = last[e.kind];
    if (prev !== undefined && e.t - prev < MIN_GAP[e.kind]) continue;
    last[e.kind] = e.t;
    out.push({t: e.t, kind: e.kind, volume: VOLUME[e.kind] * (e.gain ?? 1)});
  }
  return out;
}

// Background music volume at time t: fades in and out, and ducks under the voice.
export function musicVolume(base: number, t: number, duration: number, speech: {start: number; end: number}[]): number {
  const fade = Math.min(1, t / 0.8, Math.max(0, (duration - t) / 1.5));
  let speaking = false;
  let lo = 0;
  let hi = speech.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const w = speech[mid];
    if (t < w.start - 0.25) hi = mid - 1;
    else if (t > w.end + 0.35) lo = mid + 1;
    else {
      speaking = true;
      break;
    }
  }
  return base * fade * (speaking ? 0.55 : 1);
}
